import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadGeckoData(){const e=readFileSync(resolve(__dirname,"../../indian-golden-gecko-explorer/gecko-data.js"),"utf-8");return new Function(e+"\nreturn { GECKO_INFO, TAXONOMY_DATA, ECOLOGY_BEHAVIOUR, INTERESTING_FACTS, GALLERY_IMAGES, REFERENCES };")()}describe("Indian Golden Gecko Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadGeckoData()}),describe("GECKO_INFO metadata",()=>{it("contains correct species metadata and Eastern Ghats endemism",()=>{expect(e.GECKO_INFO.id).toBe("indian-golden-gecko"),expect(e.GECKO_INFO.scientificName).toBe("Calodactylodes aureus"),expect(e.GECKO_INFO.endemicRegion).toContain("Eastern Ghats"),expect(e.GECKO_INFO.protectionStatus).toContain("Schedule I")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.GECKO_INFO.quickStats)).toBe(!0),expect(e.GECKO_INFO.quickStats.length).toBe(6)})}),describe("TAXONOMY_DATA",()=>{it("contains valid taxonomy classification",()=>{expect(e.TAXONOMY_DATA.class).toBe("Reptilia"),expect(e.TAXONOMY_DATA.family).toBe("Gekkonidae"),expect(e.TAXONOMY_DATA.genus).toBe("Calodactylodes")})}),describe("ECOLOGY_BEHAVIOUR",()=>{it("contains required sections",()=>{expect(e.ECOLOGY_BEHAVIOUR.introduction).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.distribution).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.habitat).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.behaviour).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.conservation).toBeDefined()})}),describe("INTERESTING_FACTS & GALLERY",()=>{it("has non-empty facts and gallery images",()=>{expect(Array.isArray(e.INTERESTING_FACTS)).toBe(!0),expect(e.INTERESTING_FACTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2)})})});